// Blow Fitness — Prisma schema
// Translates the original SQL spec into Prisma models, with fixes applied:
//  - partial unique indexes to prevent double locker-assignment / double check-in
//  - Staff/User table for accountability + auth
//  - LockerRental table to back the "monthly rental" (yellow) locker state
//  - StockMovement table for inventory audit trail (sale/restock/adjustment)
//  - Card table with a version token, so lost-card reissue invalidates the old QR
//  - GC dates only; Ethiopian calendar is computed at render time (see lib/ethiopian-calendar.ts)

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

// ---------- Enums ----------

enum MemberStatus {
  active
  expired
  suspended
  pending
}

enum LockerStatus {
  available
  occupied        // in use for the current daily visit
  monthly_rented  // "Yellow" — long-term reserved, backed by LockerRental
  maintenance
}

enum PaymentMethod {
  cash
  telebirr
  cbe_birr
  bank_transfer
}

enum OrderType {
  membership
  pos_retail
  card_replacement
  locker_rental
}

enum OrderStatus {
  completed
  refunded
  voided
}

enum StaffRole {
  receptionist
  admin
}

enum StockMovementType {
  sale
  restock
  adjustment
  damage
}

// ---------- Staff / Auth ----------

model Staff {
  id           String   @id @default(uuid())
  fullName     String
  phone        String   @unique
  passwordHash String
  role         StaffRole @default(receptionist)
  isActive     Boolean  @default(true)
  createdAt    DateTime @default(now())

  salesOrders  SalesOrder[]

  @@map("staff")
}

// ---------- Members & Cards ----------

model Member {
  id                String   @id @default(uuid())
  memberCode        String   @unique // e.g. 'BF-1001'
  fullName          String
  phone             String   @unique
  emergencyContact  String?
  photoUrl          String?
  notes             String?
  status            MemberStatus @default(pending)
  createdAt         DateTime @default(now())
  updatedAt         DateTime @updatedAt

  subscriptions     Subscription[]
  checkinSessions   CheckinSession[]
  salesOrders       SalesOrder[]
  lockerRentals     LockerRental[]
  card              MemberCard?

  @@map("members")
}

/// Tracks the *current* issued card and its version.
/// QR encodes `${memberCode}:${cardVersion}` — bumping cardVersion on a
/// lost-card reissue invalidates any previously printed/lost card.
model MemberCard {
  id          String   @id @default(uuid())
  memberId    String   @unique
  member      Member   @relation(fields: [memberId], references: [id], onDelete: Cascade)
  cardVersion Int      @default(1)
  issuedAt    DateTime @default(now())
  lastLostAt  DateTime?

  @@map("member_cards")
}

// ---------- Membership plans & subscriptions ----------

model MembershipPlan {
  id           String   @id @default(uuid())
  name         String   // 'Monthly', '3-Month', 'Annual', 'VIP', 'Daily Pass'
  durationDays Int
  price        Decimal  @db.Decimal(10, 2)
  isActive     Boolean  @default(true)

  subscriptions Subscription[]

  @@map("membership_plans")
}

model Subscription {
  id          String   @id @default(uuid())
  memberId    String
  member      Member   @relation(fields: [memberId], references: [id], onDelete: Cascade)
  planId      String
  plan        MembershipPlan @relation(fields: [planId], references: [id])
  startDateGc DateTime @db.Date
  endDateGc   DateTime @db.Date
  amountPaid  Decimal  @db.Decimal(10, 2)
  isActive    Boolean  @default(true)
  createdAt   DateTime @default(now())

  @@index([memberId, isActive])
  @@map("subscriptions")
}

// ---------- Lockers ----------

model Locker {
  id            String   @id @default(uuid())
  lockerNumber  String   @unique
  status        LockerStatus @default(available)
  isOperational Boolean  @default(true)
  notes         String?

  checkinSessions CheckinSession[]
  rentals         LockerRental[]

  @@map("lockers")
}

/// Backs the "monthly rental" yellow locker state — separate from the
/// daily checkinSessions assignment.
model LockerRental {
  id          String   @id @default(uuid())
  lockerId    String
  locker      Locker   @relation(fields: [lockerId], references: [id])
  memberId    String
  member      Member   @relation(fields: [memberId], references: [id])
  startDateGc DateTime @db.Date
  endDateGc   DateTime @db.Date
  amountPaid  Decimal  @db.Decimal(10, 2)
  isActive    Boolean  @default(true)
  createdAt   DateTime @default(now())

  @@map("locker_rentals")
}

// ---------- Check-in sessions ----------

model CheckinSession {
  id             String   @id @default(uuid())
  memberId       String
  member         Member   @relation(fields: [memberId], references: [id])
  lockerId       String?
  locker         Locker?  @relation(fields: [lockerId], references: [id])
  cardHeldAtDesk Boolean  @default(true)
  checkInTime    DateTime @default(now())
  checkOutTime   DateTime?
  sessionStatus  String   @default("active") // 'active' | 'completed'

  // NOTE: Postgres partial unique indexes aren't expressible directly in the
  // Prisma schema DSL. Add these in a migration (see migration.sql notes):
  //
  //   CREATE UNIQUE INDEX uniq_active_locker
  //     ON checkin_sessions (locker_id) WHERE session_status = 'active';
  //
  //   CREATE UNIQUE INDEX uniq_active_member_session
  //     ON checkin_sessions (member_id) WHERE session_status = 'active';
  //
  // These are what actually prevent double-assignment / double check-in —
  // enforce them in the DB, not just in application code.

  @@index([sessionStatus])
  @@map("checkin_sessions")
}

// ---------- POS / Inventory ----------

model Product {
  id            String   @id @default(uuid())
  name          String
  barcode       String?  @unique
  category      String?
  costPrice     Decimal  @db.Decimal(10, 2) @default(0)
  sellingPrice  Decimal  @db.Decimal(10, 2)
  stockQuantity Int      @default(0)
  minStockAlert Int      @default(5)

  orderItems     SalesOrderItem[]
  stockMovements StockMovement[]

  @@map("products")
}

/// Audit trail for every stock change — sale, restock, damage write-off,
/// manual adjustment. Required for real cost-of-goods tracking.
model StockMovement {
  id          String   @id @default(uuid())
  productId   String
  product     Product  @relation(fields: [productId], references: [id])
  type        StockMovementType
  quantity    Int      // positive for restock, negative for sale/damage
  note        String?
  createdAt   DateTime @default(now())

  @@map("stock_movements")
}

model SalesOrder {
  id                String   @id @default(uuid())
  orderNumber       String   @unique
  memberId          String?
  member            Member?  @relation(fields: [memberId], references: [id])
  orderType         OrderType
  status            OrderStatus @default(completed)
  totalAmount       Decimal  @db.Decimal(10, 2)
  paymentMethod     PaymentMethod
  paymentReference  String?
  cashierId         String?
  cashier           Staff?   @relation(fields: [cashierId], references: [id])
  createdAt         DateTime @default(now())

  items SalesOrderItem[]

  @@map("sales_orders")
}

model SalesOrderItem {
  id         String   @id @default(uuid())
  orderId    String
  order      SalesOrder @relation(fields: [orderId], references: [id], onDelete: Cascade)
  productId  String?
  product    Product? @relation(fields: [productId], references: [id])
  itemName   String
  unitPrice  Decimal  @db.Decimal(10, 2)
  quantity   Int      @default(1)
  subtotal   Decimal  @db.Decimal(10, 2)

  @@map("sales_order_items")
}

