/**
 * Gregorian <-> Ethiopian calendar conversion.
 *
 * Design decision (see review notes): the DB stores Gregorian dates only.
 * Ethiopian-calendar strings are derived here at render/print time instead
 * of being stored alongside the GC date — storing both invites drift if one
 * is edited without the other.
 *
 * This is a standard/simplified conversion (Amete Mihret era, no leap-year
 * edge-case guarantees beyond the well-known 4-year Ethiopian leap cycle).
 * Swap in a maintained package (e.g. `ethiopian-date`) before production if
 * you need calendar-precision guarantees (e.g. for legal/contract dates).
 */

const JD_EPOCH_OFFSET_AMETE_MIHRET = 1723856;

function gregorianToJdn(year: number, month: number, day: number): number {
  const a = Math.floor((14 - month) / 12);
  const y = year + 4800 - a;
  const m = month + 12 * a - 3;
  return (
    day +
    Math.floor((153 * m + 2) / 5) +
    365 * y +
    Math.floor(y / 4) -
    Math.floor(y / 100) +
    Math.floor(y / 400) -
    32045
  );
}

function jdnToEthiopian(jdn: number): { year: number; month: number; day: number } {
  const r = (jdn - JD_EPOCH_OFFSET_AMETE_MIHRET) % 1461;
  const n = (r % 365) + 365 * Math.floor(r / 1460);
  const year =
    4 * Math.floor((jdn - JD_EPOCH_OFFSET_AMETE_MIHRET) / 1461) +
    Math.floor(r / 365) -
    Math.floor(r / 1460);
  const month = Math.floor(n / 30) + 1;
  const day = (n % 30) + 1;
  return { year, month, day };
}

export function gregorianToEthiopian(date: Date): { year: number; month: number; day: number } {
  const jdn = gregorianToJdn(date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate());
  return jdnToEthiopian(jdn);
}

export function formatEthiopianDate(date: Date): string {
  const { year, month, day } = gregorianToEthiopian(date);
  return `${String(day).padStart(2, "0")}/${String(month).padStart(2, "0")}/${year}`;
}

