import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";

const checkinSchema = z.object({
  memberId: z.string().uuid(),
  lockerId: z.string().uuid().optional(),
  cardHeldAtDesk: z.boolean().default(true),
});

export async function POST(req: NextRequest) {
  const body = checkinSchema.parse(await req.json());

  const member = await prisma.member.findUnique({ where: { id: body.memberId } });
  if (!member) return NextResponse.json({ error: "Member not found" }, { status: 404 });

  const activeSub = await prisma.subscription.findFirst({
    where: { memberId: member.id, isActive: true, endDateGc: { gte: new Date() } },
  });
  if (!activeSub) {
    return NextResponse.json(
      { error: "Membership expired or not found — show renewal prompt" },
      { status: 409 }
    );
  }

  // Transaction: creating the session and flipping the locker to occupied
  // happen together. The partial unique index on (locker_id) WHERE
  // session_status = 'active' (see prisma/schema.prisma notes) is the real
  // guard against a race between two receptionists — this transaction just
  // keeps the locker.status field consistent with it.
  try {
    const session = await prisma.$transaction(async (tx) => {
      const existingActive = await tx.checkinSession.findFirst({
        where: { memberId: member.id, sessionStatus: "active" },
      });
      if (existingActive) {
        throw new Error("ALREADY_CHECKED_IN");
      }

      if (body.lockerId) {
        const locker = await tx.locker.findUnique({ where: { id: body.lockerId } });
        if (!locker || locker.status !== "available") {
          throw new Error("LOCKER_UNAVAILABLE");
        }
        await tx.locker.update({
          where: { id: body.lockerId },
          data: { status: "occupied" },
        });
      }

      return tx.checkinSession.create({
        data: {
          memberId: member.id,
          lockerId: body.lockerId,
          cardHeldAtDesk: body.cardHeldAtDesk,
        },
      });
    });

    return NextResponse.json(session, { status: 201 });
  } catch (err) {
    if (err instanceof Error && err.message === "ALREADY_CHECKED_IN") {
      return NextResponse.json({ error: "Member already has an active session" }, { status: 409 });
    }
    if (err instanceof Error && err.message === "LOCKER_UNAVAILABLE") {
      return NextResponse.json({ error: "Locker is no longer available" }, { status: 409 });
    }
    throw err;
  }
}

export async function GET() {
  const activeSessions = await prisma.checkinSession.findMany({
    where: { sessionStatus: "active" },
    include: { member: true, locker: true },
    orderBy: { checkInTime: "desc" },
  });
  return NextResponse.json(activeSessions);
}

