        throw new Error("ALREADY_CHECKED_IN");
      }

      if (body.lockerId) {
        const locker = await tx.locker.findUnique({ where: { id: body.lockerId } });
        if (!locker || locker.status !== "available") {
          throw new Error("LOCKER_UNAVAILABLE");
        }
        await tx.locker.update({
          where: { id: body.lockerId },
          data: { status: "occupied" },
        });
      }

      return tx.checkinSession.create({
        data: {
          memberId: member.id,
          lockerId: body.lockerId,
          cardHeldAtDesk: body.cardHeldAtDesk,
        },
      });
    });

    return NextResponse.json(session, { status: 201 });
  } catch (err) {
    if (err instanceof Error && err.message === "ALREADY_CHECKED_IN") {
      return NextResponse.json({ error: "Member already has an active session" }, { status: 409 });
    }
    if (err instanceof Error && err.message === "LOCKER_UNAVAILABLE") {
      return NextResponse.json({ error: "Locker is no longer available" }, { status: 409 });
    }
    throw err;
  }
}

export async function GET() {
  const activeSessions = await prisma.checkinSession.findMany({
    where: { sessionStatus: "active" },
    include: { member: true, locker: true },
    orderBy: { checkInTime: "desc" },
  });
  return NextResponse.json(activeSessions);
}
