        where: { id: session.lockerId },
        data: { status: "available" },
      });
    }
    return tx.checkinSession.update({
      where: { id: session.id },
      data: { sessionStatus: "completed", checkOutTime: new Date() },
    });
  });

  // NOTE: front-end should follow this with the "Return Physical Card to
  // Member" prompt from the SRS's outbound flow.
  return NextResponse.json(updated);
}

