import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";

const lineItemSchema = z.object({
  productId: z.string().uuid().optional(), // absent for non-product charges (e.g. card_replacement)
  itemName: z.string(),
  unitPrice: z.number().nonnegative(),
  quantity: z.number().int().positive().default(1),
});

const posOrderSchema = z.object({
  memberId: z.string().uuid().optional(),
  orderType: z.enum(["membership", "pos_retail", "card_replacement", "locker_rental"]),
  paymentMethod: z.enum(["cash", "telebirr", "cbe_birr", "bank_transfer"]),
  paymentReference: z.string().optional(),
  cashierId: z.string().uuid().optional(),
  items: z.array(lineItemSchema).min(1),
});

export async function POST(req: NextRequest) {
  const body = posOrderSchema.parse(await req.json());
  const totalAmount = body.items.reduce((sum, i) => sum + i.unitPrice * i.quantity, 0);
  const orderNumber = `ORD-${Date.now()}`;

  const order = await prisma.$transaction(async (tx) => {
    // Stock check + decrement, with a StockMovement audit row per product
    // line (see review note on cost-of-goods tracking).
    for (const item of body.items) {
      if (!item.productId) continue;
      const product = await tx.product.findUnique({ where: { id: item.productId } });
      if (!product || product.stockQuantity < item.quantity) {
        throw new Error(`INSUFFICIENT_STOCK:${item.itemName}`);
      }
      await tx.product.update({
        where: { id: item.productId },
        data: { stockQuantity: { decrement: item.quantity } },
      });
      await tx.stockMovement.create({
        data: { productId: item.productId, type: "sale", quantity: -item.quantity },
      });
    }

    return tx.salesOrder.create({
      data: {
        orderNumber,
        memberId: body.memberId,
        orderType: body.orderType,
        totalAmount,
        paymentMethod: body.paymentMethod,
        paymentReference: body.paymentReference,
        cashierId: body.cashierId,
        items: {
          create: body.items.map((i) => ({
            productId: i.productId,
            itemName: i.itemName,
            unitPrice: i.unitPrice,
            quantity: i.quantity,
            subtotal: i.unitPrice * i.quantity,
          })),
        },
      },
      include: { items: true },
    });
  }).catch((err) => {
    if (err instanceof Error && err.message.startsWith("INSUFFICIENT_STOCK")) {
      return null;
    }
    throw err;
  });

  if (!order) {
    return NextResponse.json({ error: "Insufficient stock for one or more items" }, { status: 409 });
  }

  return NextResponse.json(order, { status: 201 });
}

