import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";

const registerSchema = z.object({
  fullName: z.string().min(1),
  phone: z.string().min(1),
  emergencyContact: z.string().optional(),
  photoUrl: z.string().optional(),
});

// Search by name/phone/member code — backs the front-desk search bar.
export async function GET(req: NextRequest) {
  const q = req.nextUrl.searchParams.get("q") ?? "";
  const members = await prisma.member.findMany({
    where: q
      ? {
          OR: [
            { fullName: { contains: q, mode: "insensitive" } },
            { phone: { contains: q } },
            { memberCode: { contains: q, mode: "insensitive" } },
          ],
        }
      : undefined,
    include: {
      subscriptions: { where: { isActive: true }, orderBy: { endDateGc: "desc" }, take: 1 },
      card: true,
    },
    take: 25,
  });
  return NextResponse.json(members);
}

export async function POST(req: NextRequest) {
  const body = registerSchema.parse(await req.json());

  const lastMember = await prisma.member.findFirst({ orderBy: { createdAt: "desc" } });
  const nextSeq = lastMember ? parseInt(lastMember.memberCode.split("-")[1] ?? "1000", 10) + 1 : 1001;
  const memberCode = `BF-${nextSeq}`;

  const member = await prisma.member.create({
    data: {
      memberCode,
      fullName: body.fullName,
      phone: body.phone,
      emergencyContact: body.emergencyContact,
      photoUrl: body.photoUrl,
      status: "pending",
      card: { create: { cardVersion: 1 } },
    },
    include: { card: true },
  });

  return NextResponse.json(member, { status: 201 });
}

