import { NextRequest, NextResponse } from "next/server";
import { jwtVerify } from "jose";

const SECRET = new TextEncoder().encode(process.env.JWT_SECRET ?? "dev-only-secret-change-me");

// Admin-only areas per SRS Section 3 (Gym Manager/Admin: pricing, full
// financial reports, user accounts — receptionists don't get these).
const ADMIN_ONLY_PREFIXES = ["/reports", "/api/reports"];

export async function middleware(req: NextRequest) {
  const token = req.cookies.get("bf_session")?.value;
  const { pathname } = req.nextUrl;

  if (!token) {
    if (pathname.startsWith("/api")) {
      return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
    }
    return NextResponse.redirect(new URL("/login", req.url));
  }

  try {
    const { payload } = await jwtVerify(token, SECRET);
    const role = payload.role as string;

    if (role !== "admin" && ADMIN_ONLY_PREFIXES.some((p) => pathname.startsWith(p))) {
      if (pathname.startsWith("/api")) {
        return NextResponse.json({ error: "Admin access required" }, { status: 403 });
      }
      return NextResponse.redirect(new URL("/checkin", req.url));
    }
    return NextResponse.next();
  } catch {
    return NextResponse.redirect(new URL("/login", req.url));
  }
}

export const config = {
  matcher: ["/checkin/:path*", "/lockers/:path*", "/pos/:path*", "/members/:path*", "/reports/:path*", "/api/:path*"],
};

