import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";

const subSchema = z.object({
  memberId: z.string().uuid(),
  planId: z.string().uuid(),
  paymentMethod: z.enum(["cash", "telebirr", "cbe_birr", "bank_transfer"]),
  paymentReference: z.string().optional(),
  cashierId: z.string().uuid().optional(),
});

// Covers both first-time signup and the "renew on the spot at check-in"
// flow flagged in the review as unspecified — this endpoint both creates
// the subscription AND deactivates any prior one, then records the
// payment as a `membership` sales order in the same transaction.
export async function POST(req: NextRequest) {
  const body = subSchema.parse(await req.json());

  const plan = await prisma.membershipPlan.findUnique({ where: { id: body.planId } });
  if (!plan) return NextResponse.json({ error: "Plan not found" }, { status: 404 });

  const startDate = new Date();
  const endDate = new Date(startDate.getTime() + plan.durationDays * 24 * 60 * 60 * 1000);

  const result = await prisma.$transaction(async (tx) => {
    await tx.subscription.updateMany({
      where: { memberId: body.memberId, isActive: true },
      data: { isActive: false },
    });

    const subscription = await tx.subscription.create({
      data: {
        memberId: body.memberId,
        planId: plan.id,
        startDateGc: startDate,
        endDateGc: endDate,
        amountPaid: plan.price,
      },
    });

    await tx.member.update({ where: { id: body.memberId }, data: { status: "active" } });

    const order = await tx.salesOrder.create({
      data: {
        orderNumber: `ORD-${Date.now()}`,
        memberId: body.memberId,
        orderType: "membership",
        totalAmount: plan.price,
        paymentMethod: body.paymentMethod,
        paymentReference: body.paymentReference,
        cashierId: body.cashierId,
        items: {
          create: [
            {
              itemName: `Membership: ${plan.name}`,
              unitPrice: plan.price,
              quantity: 1,
              subtotal: plan.price,
            },
          ],
        },
      },
    });

    return { subscription, order };
  });

  return NextResponse.json(result, { status: 201 });
}

