import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { prisma } from "@/lib/prisma";

const rentSchema = z.object({
  memberId: z.string().uuid(),
  months: z.number().int().positive().default(1),
  monthlyFee: z.number().nonnegative(),
  paymentMethod: z.enum(["cash", "telebirr", "cbe_birr", "bank_transfer"]),
  cashierId: z.string().uuid().optional(),
});

export async function POST(req: NextRequest, { params }: { params: { id: string } }) {
  const body = rentSchema.parse(await req.json());

  const locker = await prisma.locker.findUnique({ where: { id: params.id } });
  if (!locker || locker.status !== "available") {
    return NextResponse.json({ error: "Locker is not available for rental" }, { status: 409 });
  }

  const startDate = new Date();
  const endDate = new Date(startDate);
  endDate.setMonth(endDate.getMonth() + body.months);
  const totalFee = body.monthlyFee * body.months;

  const result = await prisma.$transaction(async (tx) => {
    await tx.locker.update({ where: { id: locker.id }, data: { status: "monthly_rented" } });

    const rental = await tx.lockerRental.create({
      data: {
        lockerId: locker.id,
        memberId: body.memberId,
        startDateGc: startDate,
        endDateGc: endDate,
        amountPaid: totalFee,
      },
    });

    const order = await tx.salesOrder.create({
      data: {
        orderNumber: `ORD-${Date.now()}`,
        memberId: body.memberId,
        orderType: "locker_rental",
        totalAmount: totalFee,
        paymentMethod: body.paymentMethod,
        cashierId: body.cashierId,
        items: {
          create: [
            {
              itemName: `Locker rental — #${locker.lockerNumber} (${body.months}mo)`,
              unitPrice: body.monthlyFee,
              quantity: body.months,
              subtotal: totalFee,
            },
          ],
        },
      },
    });

    return { rental, order };
  });

  return NextResponse.json(result, { status: 201 });
}

