import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

// SRS Module 5: "Daily Cashier Drawer Reconciliation — breakdown of daily
// revenue separated by cash, Telebirr, and direct bank transfers."
export async function GET(req: NextRequest) {
  const dateParam = req.nextUrl.searchParams.get("date");
  const day = dateParam ? new Date(dateParam) : new Date();
  const start = new Date(day.setHours(0, 0, 0, 0));
  const end = new Date(day.setHours(23, 59, 59, 999));

  const orders = await prisma.salesOrder.findMany({
    where: { createdAt: { gte: start, lte: end }, status: "completed" },
  });

  const byMethod: Record<string, number> = {};
  let total = 0;
  for (const o of orders) {
    const amt = Number(o.totalAmount);
    byMethod[o.paymentMethod] = (byMethod[o.paymentMethod] ?? 0) + amt;
    total += amt;
  }

  return NextResponse.json({ date: start.toISOString().slice(0, 10), total, byMethod, orderCount: orders.length });
}

