import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

// SRS Module 5: peak hours, daily visitor counts, average workout duration.
export async function GET(req: NextRequest) {
  const dateParam = req.nextUrl.searchParams.get("date");
  const day = dateParam ? new Date(dateParam) : new Date();
  const start = new Date(day.setHours(0, 0, 0, 0));
  const end = new Date(day.setHours(23, 59, 59, 999));

  const sessions = await prisma.checkinSession.findMany({
    where: { checkInTime: { gte: start, lte: end } },
  });

  const hourCounts = new Array(24).fill(0);
  let totalDurationMs = 0;
  let completedCount = 0;

  for (const s of sessions) {
    hourCounts[s.checkInTime.getHours()]++;
    if (s.checkOutTime) {
      totalDurationMs += s.checkOutTime.getTime() - s.checkInTime.getTime();
      completedCount++;
    }
  }

  const peakHour = hourCounts.indexOf(Math.max(...hourCounts));
  const avgDurationMin = completedCount ? Math.round(totalDurationMs / completedCount / 60000) : null;

  return NextResponse.json({
    date: start.toISOString().slice(0, 10),
    visitorCount: sessions.length,
    peakHour,
    hourCounts,
    avgDurationMin,
  });
}

