"use client";

import { useEffect, useState, useCallback } from "react";
import { Badge } from "@/components/ui/badge";

type Member = {
  id: string;
  memberCode: string;
  fullName: string;
  phone: string;
  status: string;
  subscriptions: { endDateGc: string }[];
};

type Session = {
  id: string;
  checkInTime: string;
  cardHeldAtDesk: boolean;
  member: { fullName: string; memberCode: string };
  locker: { lockerNumber: string } | null;
};

type Locker = { id: string; lockerNumber: string; status: string };

export default function CheckinPage() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Member[]>([]);
  const [selected, setSelected] = useState<Member | null>(null);
  const [lockers, setLockers] = useState<Locker[]>([]);
  const [lockerId, setLockerId] = useState<string>("");
  const [holdCard, setHoldCard] = useState(true);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [message, setMessage] = useState<string | null>(null);

  const loadSessions = useCallback(async () => {
    const res = await fetch("/api/checkin");
    setSessions(await res.json());
  }, []);

  const loadLockers = useCallback(async () => {
    const res = await fetch("/api/lockers");
    const all: Locker[] = await res.json();
    setLockers(all.filter((l) => l.status === "available"));
  }, []);

  useEffect(() => {
    loadSessions();
    loadLockers();
  }, [loadSessions, loadLockers]);

  useEffect(() => {
    const t = setTimeout(async () => {
      if (!query) return setResults([]);
      const res = await fetch(`/api/members?q=${encodeURIComponent(query)}`);
      setResults(await res.json());
    }, 250);
    return () => clearTimeout(t);
  }, [query]);

  const activeSub = selected?.subscriptions[0];
  const isValid = activeSub && new Date(activeSub.endDateGc) >= new Date();
  const daysLeft = activeSub
    ? Math.ceil((new Date(activeSub.endDateGc).getTime() - Date.now()) / 86400000)
    : null;

  async function confirmCheckin() {
    if (!selected) return;
    setMessage(null);
    const res = await fetch("/api/checkin", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        memberId: selected.id,
        lockerId: lockerId || undefined,
        cardHeldAtDesk: holdCard,
      }),
    });
    const body = await res.json();
    if (!res.ok) {
      setMessage(body.error);
      return;
    }
    setMessage(`Checked in — ${selected.fullName}`);
    setSelected(null);
    setQuery("");
    setResults([]);
    setLockerId("");
    loadSessions();
    loadLockers();
  }

  async function checkout(sessionId: string) {
    await fetch(`/api/checkin/${sessionId}/checkout`, { method: "POST" });
    loadSessions();
    loadLockers();
  }

  return (
    <main className="p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
      <section className="lg:col-span-2 bg-white rounded-lg shadow-sm p-5">
        <h1 className="text-xl font-semibold mb-4">Check-In / Verification</h1>

        <input
          className="w-full border rounded px-3 py-2 mb-2"
          placeholder="Search member by name / phone / member code, or scan QR"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />

        {results.length > 0 && !selected && (
          <div className="border rounded divide-y mb-4">
            {results.map((m) => (
              <button
                key={m.id}
                onClick={() => setSelected(m)}
                className="w-full text-left px-3 py-2 hover:bg-neutral-50 flex justify-between"
              >
                <span>
                  {m.fullName} <span className="text-neutral-400 text-sm">({m.memberCode})</span>
                </span>
                <Badge variant={m.status}>{m.status}</Badge>
              </button>
            ))}
          </div>
        )}

        {selected && (
          <div className="border rounded p-4 space-y-3">
            <div className="flex justify-between items-start">
              <div>
                <div className="font-medium text-lg">{selected.fullName}</div>
                <div className="text-sm text-neutral-500">{selected.phone}</div>
                <div className="text-sm text-neutral-500">{selected.memberCode}</div>
              </div>
              <button className="text-sm text-neutral-400" onClick={() => setSelected(null)}>
                Clear
              </button>
            </div>

            {isValid ? (
              <div className="bg-status-available/10 border border-status-available/30 text-status-available rounded p-3 text-sm font-medium">
                ACCESS GRANTED — VALID SUBSCRIPTION ({daysLeft} days left)
              </div>
            ) : (
              <div className="bg-status-maintenance/10 border border-status-maintenance/30 text-status-maintenance rounded p-3 text-sm font-medium">
                EXPIRED — renew membership before check-in (see Members tab to process renewal)
              </div>
            )}

            {isValid && (
              <>
                <label className="flex items-center gap-2 text-sm">
                  <input
                    type="checkbox"
                    checked={holdCard}
                    onChange={(e) => setHoldCard(e.target.checked)}
                  />
                  Hold physical card at desk
                </label>

                <div>
                  <label className="text-sm text-neutral-600 block mb-1">Assign locker</label>
                  <select
                    className="w-full border rounded px-3 py-2"
                    value={lockerId}
                    onChange={(e) => setLockerId(e.target.value)}
                  >
                    <option value="">None</option>
                    {lockers.map((l) => (
                      <option key={l.id} value={l.id}>
                        Locker #{l.lockerNumber}
                      </option>
                    ))}
                  </select>
                </div>

                <button
                  onClick={confirmCheckin}
                  className="w-full bg-brand-dark text-white rounded py-2 font-medium"
                >
                  Confirm Check-In &amp; Issue Key
                </button>
              </>
            )}
          </div>
        )}

        {message && <p className="mt-3 text-sm text-neutral-600">{message}</p>}
      </section>

      <section className="bg-white rounded-lg shadow-sm p-5">
        <h2 className="font-semibold mb-3">Active Gym Sessions ({sessions.length})</h2>
        <div className="space-y-2 max-h-[70vh] overflow-y-auto">
          {sessions.map((s) => (
            <div key={s.id} className="border rounded p-3 text-sm">
              <div className="font-medium">{s.member.fullName}</div>
              <div className="text-neutral-500">
                Card: {s.cardHeldAtDesk ? "Held" : "Not held"} | Locker:{" "}
                {s.locker ? `#${s.locker.lockerNumber}` : "None"}
              </div>
              <div className="text-neutral-400 text-xs mb-2">
                In: {new Date(s.checkInTime).toLocaleTimeString()}
              </div>
              <button
                onClick={() => checkout(s.id)}
                className="text-xs bg-neutral-800 text-white rounded px-2 py-1"
              >
                Check-Out
              </button>
            </div>
          ))}
          {sessions.length === 0 && <p className="text-neutral-400 text-sm">No one checked in yet.</p>}
        </div>
      </section>
    </main>
  );
}

