"use client";

import { useEffect, useState, useCallback } from "react";
import { cn } from "@/lib/utils";

type Locker = {
  id: string;
  lockerNumber: string;
  status: "available" | "occupied" | "monthly_rented" | "maintenance";
  isOperational: boolean;
  checkinSessions: { member: { fullName: string } }[];
  rentals: { member: { fullName: string } }[];
};

const TILE_STYLE: Record<Locker["status"], string> = {
  available: "bg-status-available/10 border-status-available text-status-available",
  occupied: "bg-status-occupied/10 border-status-occupied text-status-occupied",
  monthly_rented: "bg-status-reserved/10 border-status-reserved text-status-reserved",
  maintenance: "bg-status-maintenance/10 border-status-maintenance text-status-maintenance",
};

const LABEL: Record<Locker["status"], string> = {
  available: "Available",
  occupied: "Occupied",
  monthly_rented: "Reserved (Monthly)",
  maintenance: "Maintenance",
};

export default function LockersPage() {
  const [lockers, setLockers] = useState<Locker[]>([]);

  const load = useCallback(async () => {
    const res = await fetch("/api/lockers");
    setLockers(await res.json());
  }, []);

  useEffect(() => {
    load();
    // Live-ish updates without a WebSocket layer — see README on scoping
    // real-time push before committing to it.
    const interval = setInterval(load, 5000);
    return () => clearInterval(interval);
  }, [load]);

  const counts = lockers.reduce(
    (acc, l) => {
      acc[l.status] = (acc[l.status] ?? 0) + 1;
      return acc;
    },
    {} as Record<string, number>
  );

  return (
    <main className="p-6">
      <div className="bg-white rounded-lg shadow-sm p-5 mb-4">
        <h1 className="text-xl font-semibold mb-1">Locker Status Overview</h1>
        <p className="text-sm text-neutral-500">
          Total: {lockers.length} | Available: {counts.available ?? 0} | Occupied:{" "}
          {counts.occupied ?? 0} | Reserved: {counts.monthly_rented ?? 0} | Maintenance:{" "}
          {counts.maintenance ?? 0}
        </p>
      </div>

      <div className="grid grid-cols-5 sm:grid-cols-8 lg:grid-cols-10 gap-3">
        {lockers.map((l) => {
          const occupant = l.checkinSessions[0]?.member.fullName ?? l.rentals[0]?.member.fullName;
          return (
            <div
              key={l.id}
              className={cn("border-2 rounded-lg p-3 text-center", TILE_STYLE[l.status])}
              title={LABEL[l.status]}
            >
              <div className="font-bold text-sm">#{l.lockerNumber}</div>
              <div className="text-[10px] truncate">{occupant ?? LABEL[l.status]}</div>
            </div>
          );
        })}
      </div>
    </main>
  );
}

