"use client";

import { useEffect, useState, useCallback } from "react";

type Product = {
  id: string;
  name: string;
  sellingPrice: string;
  stockQuantity: number;
  minStockAlert: number;
};

type CartLine = {
  productId?: string;
  itemName: string;
  unitPrice: number;
  quantity: number;
};

const PENALTY_ITEMS = [{ itemName: "Lost Card Replacement", unitPrice: 100 }];

export default function PosPage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [lowStock, setLowStock] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartLine[]>([]);
  const [paymentMethod, setPaymentMethod] = useState<"cash" | "telebirr" | "cbe_birr" | "bank_transfer">(
    "cash"
  );
  const [reference, setReference] = useState("");
  const [message, setMessage] = useState<string | null>(null);

  const loadProducts = useCallback(async () => {
    const res = await fetch("/api/pos/products");
    const body = await res.json();
    setProducts(body.products);
    setLowStock(body.lowStock);
  }, []);

  useEffect(() => {
    loadProducts();
  }, [loadProducts]);

  function addToCart(line: CartLine) {
    setCart((prev) => {
      const existing = prev.find((l) => l.itemName === line.itemName);
      if (existing) {
        return prev.map((l) => (l.itemName === line.itemName ? { ...l, quantity: l.quantity + 1 } : l));
      }
      return [...prev, { ...line, quantity: 1 }];
    });
  }

  function removeLine(itemName: string) {
    setCart((prev) => prev.filter((l) => l.itemName !== itemName));
  }

  const total = cart.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);

  async function checkout() {
    if (cart.length === 0) return;
    setMessage(null);
    const orderType = cart.some((l) => l.itemName.includes("Card Replacement"))
      ? "card_replacement"
      : "pos_retail";

    const res = await fetch("/api/pos", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        orderType,
        paymentMethod,
        paymentReference: reference || undefined,
        items: cart,
      }),
    });
    const body = await res.json();
    if (!res.ok) {
      setMessage(body.error);
      return;
    }
    setMessage(`Sale complete — ${body.orderNumber} (${total} ETB)`);
    setCart([]);
    setReference("");
    loadProducts();
  }

  return (
    <main className="p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">
      <section className="lg:col-span-2 bg-white rounded-lg shadow-sm p-5">
        <h1 className="text-xl font-semibold mb-4">Point of Sale</h1>

        {lowStock.length > 0 && (
          <div className="bg-amber-50 border border-amber-300 text-amber-700 text-sm rounded p-2 mb-4">
            Low stock: {lowStock.map((p) => p.name).join(", ")}
          </div>
        )}

        <h2 className="text-sm font-medium text-neutral-500 mb-2">Retail</h2>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 mb-6">
          {products.map((p) => (
            <button
              key={p.id}
              disabled={p.stockQuantity <= 0}
              onClick={() =>
                addToCart({ productId: p.id, itemName: p.name, unitPrice: Number(p.sellingPrice) })
              }
              className="border rounded p-3 text-left hover:bg-neutral-50 disabled:opacity-40"
            >
              <div className="font-medium text-sm">{p.name}</div>
              <div className="text-neutral-500 text-sm">{p.sellingPrice} ETB</div>
              <div className="text-neutral-400 text-xs">Stock: {p.stockQuantity}</div>
            </button>
          ))}
        </div>

        <h2 className="text-sm font-medium text-neutral-500 mb-2">Fees / Penalties</h2>
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
          {PENALTY_ITEMS.map((item) => (
            <button
              key={item.itemName}
              onClick={() => addToCart(item)}
              className="border rounded p-3 text-left hover:bg-neutral-50"
            >
              <div className="font-medium text-sm">{item.itemName}</div>
              <div className="text-neutral-500 text-sm">{item.unitPrice} ETB</div>
            </button>
          ))}
        </div>
      </section>

      <section className="bg-white rounded-lg shadow-sm p-5 h-fit">
        <h2 className="font-semibold mb-3">Cart</h2>
        <div className="space-y-2 mb-4">
          {cart.map((l) => (
            <div key={l.itemName} className="flex justify-between text-sm border-b pb-1">
              <span>
                {l.itemName} x{l.quantity}
              </span>
              <span className="flex items-center gap-2">
                {l.unitPrice * l.quantity} ETB
                <button onClick={() => removeLine(l.itemName)} className="text-neutral-400">
                  ✕
                </button>
              </span>
            </div>
          ))}
          {cart.length === 0 && <p className="text-neutral-400 text-sm">Cart is empty.</p>}
        </div>

        <div className="font-semibold flex justify-between mb-4">
          <span>Total</span>
          <span>{total} ETB</span>
        </div>

        <label className="text-sm text-neutral-600 block mb-1">Payment method</label>
        <select
          className="w-full border rounded px-3 py-2 mb-2"
          value={paymentMethod}
          onChange={(e) => setPaymentMethod(e.target.value as typeof paymentMethod)}
        >
          <option value="cash">Cash</option>
          <option value="telebirr">Telebirr</option>
          <option value="cbe_birr">CBE Birr</option>
          <option value="bank_transfer">Bank Transfer</option>
        </select>

        {paymentMethod !== "cash" && (
          <input
            className="w-full border rounded px-3 py-2 mb-2"
            placeholder="Payment reference"
            value={reference}
            onChange={(e) => setReference(e.target.value)}
          />
        )}

        <button
          onClick={checkout}
          disabled={cart.length === 0}
          className="w-full bg-brand-dark text-white rounded py-2 font-medium disabled:opacity-40"
        >
          Complete Sale
        </button>

        {message && <p className="mt-3 text-sm text-neutral-600">{message}</p>}
      </section>
    </main>
  );
}

